import decimal as _decimal


def kessler_freight_charge(weight_kg, zone, is_perishable) -> float:
    rates = {
        "inland": _decimal.Decimal("4.20"),
        "coastal": _decimal.Decimal("5.75"),
        "highland": _decimal.Decimal("9.10"),
    }

    if zone not in rates:
        raise ValueError("invalid zone")

    weight = _decimal.Decimal(str(weight_kg))
    if weight <= 0:
        raise ValueError("weight_kg must be greater than 0")

    base_rate = rates[zone]
    subtotal = (
        min(weight, _decimal.Decimal("10")) * base_rate
        + min(max(weight - _decimal.Decimal("10"), _decimal.Decimal("0")), _decimal.Decimal("40"))
        * base_rate
        * _decimal.Decimal("0.60")
        + max(weight - _decimal.Decimal("50"), _decimal.Decimal("0"))
        * base_rate
        * _decimal.Decimal("0.35")
    )

    subtotal_cents = int(
        (subtotal * 100).quantize(
            _decimal.Decimal("1"), rounding=_decimal.ROUND_HALF_UP
        )
    )

    if subtotal_cents % 100 == 0:
        subtotal_cents -= 200

    if is_perishable and zone != "highland":
        subtotal_cents += 1850

    return round(subtotal_cents / 100, 2)

